ion[List[np.ndarray], np.ndarray]:\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    Query the model to get action predictions.\\\\n\\\\n    Args:\\\\n        cfg: Configuration object with model parameters\\\\n        model: The loaded model\\\\n        obs: Observation dictionary\\\\n        task_label: Text description of the task\\\\n        processor: Model processor for inputs\\\\n        action_head: Optional action head for continuous actions\\\\n        proprio_projector: Optional proprioception projector\\\\n        noisy_action_projector: Optional noisy action projector for diffusion\\\\n        use_film: Whether to use FiLM\\\\n\\\\n    Returns:\\\\n        Union[List[np.ndarray], np.ndarray]: Predicted actions\\\\n\\\\n    Raises:\\\\n        ValueError: If model family is not supported\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    with torch.no_grad():\\\\n        if cfg.model_family == \\\\\\\"openvla\\\\\\\":\\\\n            action = get_vla_action(\\\\n                cfg=cfg,\\\\n                vla=model,\\\\n                processor=processor,\\\\n                obs=obs,\\\\n                task_label=task_label,\\\\n                action_head=action_head,\\\\n                proprio_projector=proprio_projector,\\\\n                noisy_action_projector=noisy_action_projector,\\\\n                use_film=use_film,\\\\n            )\\\\n        else:\\\\n            raise ValueError(f\\\\\\\"Unsupported model family: {cfg.model_family}\\\\\\\")\\\\n\\\\n    return action\\\\n\\\\n\\\\ndef normalize_gripper_action(action: np.ndarray, binarize: bool = True) -> np.ndarray:\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    Normalize gripper action from [0,1] to [-1,+1] range.\\\\n\\\\n    This is necessary for some environments because the dataset wrapper\\\\n    standardizes gripper actions to [0,1]. Note that unlike the other action\\\\n    dimensions, the gripper action is not normalized to [-1,+1] by default.\\\\n\\\\n    Normalization formula: y = 2 * (x - orig_low) / (orig_high - orig_low) - 1\\\\n\\\\n    Args:\\\\n        action: Action array with gripper action in the last dimension\\\\n        binarize: Whether to binarize gripper action to -1 or +1\\\\n\\\\n    Returns:\\\\n        np.ndarray: Action array with normalized gripper action\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    # Create a copy to avoid modifying the original\\\\n    normalized_action = action.copy()\\\\n\\\\n    # Normalize the last action dimension to [-1,+1]\\\\n    orig_low, orig_high = 0.0, 1.0\\\\n    normalized_action[..., -1] = 2 * (normalized_action[..., -1] - orig_low) / (orig_high - orig_low) - 1\\\\n\\\\n    if binarize:\\\\n        # Binarize to -1 or +1\\\\n        normalized_action[..., -1] = np.sign(normalized_action[..., -1])\\\\n\\\\n    return normalized_action\\\\n\\\\n\\\\ndef invert_gripper_action(action: np.ndarray) -> np.ndarray:\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    Flip the sign of the gripper action (last dimension of action vector).\\\\n\\\\n    This is necessary for environments where -1 = open, +1 = close, since\\\\n    the RLDS dataloader aligns gripper actions such that 0 = close, 1 = open.\\\\n\\\\n    Args:\\\\n        action: Action array with gripper action in the last dimension\\\\n\\\\n    Returns:\\\\n        np.ndarray: Action array with inverted gripper action\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    # Create a copy to avoid modifying the original\\\\n    inverted_action = action.copy()\\\\n\\\\n    # Invert the gripper action\\\\n    inverted_action[..., -1] *= -1.0\\\\n\\\\n    return inverted_action\\\\n\\\", \\\"stderr\\\": \\\"\\\", \\\"return_code\\\": 0}, \\\"error\\\": null, \\\"metadata\\\": {\\\"elapsed_seconds\\\": 0.35}}\"}","structuredContent":{"result":"{\"success\": true, \"data\": {\"stdout\": \"\\\"\\\"\\\"Utils for evaluating robot policies in various environments.\\\"\\\"\\\"\\n\\nimport os\\nimport random\\nimport time\\nfrom typing import Any, Dict, List, Optional, Union\\n\\nimport numpy a